// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();



export type CasinoOverlayProps = Record<string, any>;

// Helpers
const getSuitSymbolAndColor = (suitName: "Club" | "Heart" | "Spade" | "Diamond") => {
  switch (suitName) {
    case "Club":
      return { symbol: "♣", isRed: false };
    case "Heart":
      return { symbol: "♥", isRed: true };
    case "Spade":
      return { symbol: "♠", isRed: false };
    case "Diamond":
      return { symbol: "♦", isRed: true };
    default:
      return { symbol: "♣", isRed: false };
  }
};

const getValueSymbol = (valueName: string) => {
  switch (valueName) {
    case "Jack":
      return "J";
    case "Queen":
      return "Q";
    case "King":
      return "K";
    case "Ace":
      return "A";
    default:
      return valueName;
  }
};

const CardFace: React.FC<{
  valueProp: string;
  suitProp: "Club" | "Heart" | "Spade" | "Diamond";
  accentGold: string;
  cardContentSize: number;
}> = ({ valueProp, suitProp, accentGold, cardContentSize }) => {
  const { symbol: suitSymbol, isRed } = getSuitSymbolAndColor(suitProp);
  const displayValue = getValueSymbol(valueProp);

  return (
    <div
      style={{
        width: 140,
        height: 196,
        backgroundColor: "#F9F9F9",
        borderRadius: 14,
        boxShadow: "0 10px 28px rgba(0,0,0,0.5)",
        position: "relative",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: isRed ? "#E63946" : "#111111",
        fontFamily: interFamily,
        border: `2px solid ${accentGold}40`,
        boxSizing: "border-box",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: 4,
          fontSize: cardContentSize,
          fontWeight: 900,
          lineHeight: 1,
        }}
      >
        <span>{displayValue}</span>
        <span>{suitSymbol}</span>
      </div>
    </div>
  );
};

const CardBack: React.FC<{ accentGold: string }> = ({ accentGold }) => {
  return (
    <div
      style={{
        width: 140,
        height: 196,
        backgroundColor: "#111111",
        borderRadius: 14,
        border: "3px solid #EAEAEA",
        position: "relative",
        overflow: "hidden",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        boxSizing: "border-box",
      }}
    >
      <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          <pattern id="card-pattern" width="16" height="16" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
            <rect width="3" height="16" fill={accentGold} fillOpacity="0.3" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#card-pattern)" />
      </svg>
      <div style={{ width: 70, height: 110, backgroundColor: "#111", border: `3px solid ${accentGold}80`, zIndex: 1, borderRadius: 8 }} />
    </div>
  );
};

const CasinoOverlay: React.FC<CasinoOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  dealerHand = [
    { value: "7", suit: "Heart" },
    { value: "2", suit: "Club" },
  ],
  highlightWinner = "Dealer",
  accentGold = "#D4AF37",
  boxScale = 1.3,
  boxPositionX = 0,
  boxPositionY = -40,
  cardFlipStartFrame = 140,
  cardFlipStagger = 10,
  equityText = "Equity: 89%",
  equityBoxScale = 1.3,
  equityBoxPositionX = 0,
  equityBoxPositionY = 150,
  equityBoxStartFrame = 180,
  cardContentSize = 48,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Timeline
  const overlayEnter = spring({ frame, fps, config: { damping: 16 } });
  const baseOpacity = interpolate(overlayEnter, [0, 1], [0, 1]);
  const baseTranslateX = interpolate(overlayEnter, [0, 1], [-40, 0]);

  const showWinnerProgress = spring({ frame: frame - 175, fps, config: { damping: 12 } });
  const dealerWinIntensity = highlightWinner === "Dealer" ? interpolate(showWinnerProgress, [0, 1], [0, 1]) : 0;

  // Equity Box Entrance
  const equityEnter = spring({ frame: frame - equityBoxStartFrame, fps, config: { damping: 14 } });
  const equityOpacity = interpolate(equityEnter, [0, 1], [0, 1]);
  const equityTranslateY = interpolate(equityEnter, [0, 1], [30, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* DEALER ZONE */}
      <AbsoluteFill
        style={{
          opacity: baseOpacity,
          transform: `scale(${boxScale}) translate(${baseTranslateX + boxPositionX}px, ${boxPositionY}px)`,
          transformOrigin: "center center",
          transition: "none",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            padding: "36px 48px",
            borderRadius: 24,
            backgroundColor: "rgba(18, 18, 20, 0.85)",
            backdropFilter: "blur(20px)",
            border: `2px solid rgba(255,255,255,${0.05 + dealerWinIntensity * 0.3})`,
            boxShadow: `0 16px 48px rgba(0,0,0,0.6), 0 0 ${dealerWinIntensity * 50}px ${accentGold}50`,
            transition: "none",
          }}
        >
          <div style={{ display: "flex", gap: 20 }}>
            {dealerHand.map((card, idx) => {
              const flipStart = cardFlipStartFrame + idx * cardFlipStagger;
              const flipProgress = spring({ frame: frame - flipStart, fps, config: { damping: 14 } });
              const scaleX = interpolate(flipProgress, [0, 0.5, 1], [1, 0, 1], { extrapolateRight: "clamp" });
              const isFlipped = flipProgress > 0.5;

              const enterProgress = spring({ frame: frame - 10 - idx * 5, fps, config: { damping: 14 } });
              const y = interpolate(enterProgress, [0, 1], [-30, 0]);
              const opacity = enterProgress;

              return (
                <div key={idx} style={{ transform: `translateY(${y}px) scaleX(${scaleX})`, opacity, transition: "none" }}>
                  {isFlipped ? (
                    <CardFace valueProp={card.value} suitProp={card.suit} accentGold={accentGold} cardContentSize={cardContentSize} />
                  ) : (
                    <CardBack accentGold={accentGold} />
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>

      {/* EQUITY ZONE */}
      <AbsoluteFill
        style={{
          opacity: equityOpacity,
          transform: `scale(${equityBoxScale}) translate(${equityBoxPositionX}px, ${equityBoxPositionY}px)`,
          transformOrigin: "center center",
          transition: "none",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            padding: "16px 32px",
            borderRadius: 16,
            backgroundColor: "rgba(18, 18, 20, 0.85)",
            backdropFilter: "blur(20px)",
            border: "2px solid rgba(255,255,255,0.05)",
            boxShadow: "0 12px 36px rgba(0,0,0,0.5)",
            transform: `translateY(${equityTranslateY}px)`,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: montserratFamily,
              fontSize: 22,
              fontWeight: 800,
              color: "#FFFFFF",
              letterSpacing: "1px",
              textTransform: "uppercase",
            }}
          >
            {equityText}
          </span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CasinoOverlay;